   463	static unsigned
   464	xmlDictHashName(unsigned seed, const xmlChar* data, size_t maxLen,
   465	                size_t *plen) {
   466	    unsigned h1, h2;
   467	    size_t i;
   468	
   469	    HASH_INIT(h1, h2, seed);
   470	
   471	    for (i = 0; i < maxLen && data[i]; i++) {
   472	        HASH_UPDATE(h1, h2, data[i]);
   473	    }
   474	
   475	    HASH_FINISH(h1, h2);
   476	
   477	    *plen = i;
   478	    return(h2 | MAX_HASH_SIZE);
   479	}
